-- LOCAL ONLY. Monthly factual conference; HR27 informative HE; no salaries, money or external payroll.
BEGIN;SET LOCAL lock_timeout='10s';SET LOCAL search_path=pg_catalog;LOCK TABLE public.quadro_pessoal_alocacao IN ROW EXCLUSIVE MODE;SELECT pg_advisory_xact_lock(61001,1);LOCK TABLE public.folha_registos,public.folha_he,public.folha_historico,public.folha_gestao_historico,public.folha_avaliacoes_diarias,public.folha_jornadas_individuais_versoes,public.folha_config_empresa,public.colaboradores,public.ausencias,public.folha_vencimentos,public.quadro_pessoal_movimentos,public.quadro_equipa_permanencias,folha_privado.operacoes IN SHARE ROW EXCLUSIVE MODE;
DO $hours_dependencies$ BEGIN
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.ator()') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='176c4fb030401fb45c89f3cd1616a9d26e9e15b691ff524a33dfc8d233c6b079' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) x WHERE x.grantee<>proowner )) THEN RAISE EXCEPTION 'HORAS_AUTHORIZATION_DEPENDENCY_DRIFT: folha_privado.ator()';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.obra(uuid,boolean)') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='731f5289cd29bdb7f7d69723fabb76cbb8b8e577bb474c679f991c7271d9788e' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) x WHERE x.grantee<>proowner )) THEN RAISE EXCEPTION 'HORAS_AUTHORIZATION_DEPENDENCY_DRIFT: folha_privado.obra(uuid,boolean)';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.lock_dia(uuid,date)') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='b29022304f316e25dd34bae7a1e1906a0dfd72bd041a1d658338cc8394745502' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) x WHERE x.grantee<>proowner )) THEN RAISE EXCEPTION 'HORAS_AUTHORIZATION_DEPENDENCY_DRIFT: folha_privado.lock_dia(uuid,date)';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.local(uuid,uuid,boolean)') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='9eb2f0d8b7e52d5280f0798c48cb8ec84377281c1e13706bc066b1cf3765070b' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) x WHERE x.grantee<>proowner )) THEN RAISE EXCEPTION 'HORAS_AUTHORIZATION_DEPENDENCY_DRIFT: folha_privado.local(uuid,uuid,boolean)';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('public.fn_folha_contexto_v2(date,uuid)') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='e5ca6e224708a655a9c778fa6a5701b39e6c0aab8dbf0a01a87ffb77d42ea095' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) x WHERE x.grantee<>proowner AND x.grantee<>'authenticated'::regrole)) THEN RAISE EXCEPTION 'HORAS_AUTHORIZATION_DEPENDENCY_DRIFT: public.fn_folha_contexto_v2(date,uuid)';END IF;
END $hours_dependencies$;DO $base$ BEGIN IF current_user<>'postgres' OR session_user<>'postgres' THEN RAISE EXCEPTION 'OWNER_REQUIRED';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('public.fn_folha_conferencia_contexto_v3(uuid,date)') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='3c66b79ac1882a756ccd430fa403e5c4c195c195e8ddb77ae7699dc80b78ee6c' AND (SELECT array_agg(x::text ORDER BY x::text) FROM unnest(proacl) x)=ARRAY['authenticated=X/postgres','postgres=X/postgres']) THEN RAISE EXCEPTION 'MONTHLY_FUNCTION_DRIFT: public.fn_folha_conferencia_contexto_v3(uuid,date)';END IF;
END $base$;
DO $absent$ BEGIN IF to_regclass('public.folha_conferencias_mensais') IS NOT NULL OR to_regclass('public.folha_conferencia_historico') IS NOT NULL OR to_regprocedure('folha_privado.conferencia_calcular(uuid,date)') IS NOT NULL OR to_regprocedure('folha_privado.conferencia_guardar()') IS NOT NULL OR to_regprocedure('folha_privado.conferencia_historico_guardar()') IS NOT NULL OR to_regprocedure('folha_privado.conferencia_trilho_final()') IS NOT NULL OR to_regprocedure('folha_privado.conferencia_reconciliar()') IS NOT NULL OR to_regprocedure('public.fn_folha_conferencia_v3(text,jsonb,boolean,text)') IS NOT NULL THEN RAISE EXCEPTION 'MONTHLY_PRESENT_OR_PARTIAL';END IF;END $absent$;
CREATE SCHEMA primeline_monthly_backup;REVOKE ALL ON SCHEMA primeline_monthly_backup FROM PUBLIC,anon,authenticated,service_role;
CREATE TABLE primeline_monthly_backup.contexto AS SELECT pg_get_functiondef('public.fn_folha_conferencia_contexto_v3(uuid,date)'::regprocedure) definicao;
CREATE TABLE primeline_monthly_backup.dados(tabela text PRIMARY KEY,linhas jsonb NOT NULL);
DO $copy$ DECLARE n text;BEGIN FOREACH n IN ARRAY ARRAY['public.folha_registos','public.folha_he','public.folha_historico','public.folha_gestao_historico','public.folha_avaliacoes_diarias','public.folha_jornadas_individuais_versoes','public.folha_config_empresa','public.colaboradores','public.ausencias','public.folha_vencimentos','public.quadro_pessoal_alocacao','public.quadro_pessoal_movimentos','public.quadro_equipa_permanencias','folha_privado.operacoes'] LOOP EXECUTE format('INSERT INTO primeline_monthly_backup.dados SELECT %L,coalesce(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text COLLATE "C"),''[]''::jsonb) FROM %s x',n,n::regclass);END LOOP;END $copy$;
REVOKE ALL ON ALL TABLES IN SCHEMA primeline_monthly_backup FROM PUBLIC,anon,authenticated,service_role;SELECT 'MONTHLY_BACKUP_OK' resultado;COMMIT;
